import{_ as t,o,c as r,ag as a}from"./chunks/framework.BIas3y6W.js";const m=JSON.parse('{"title":"Week 14 homework — Milestone 2: secure it, review it, hand it off","description":"","frontmatter":{"source":"weeks/14-security-and-review/homework.md"},"headers":[],"relativePath":"weeks/14-security-and-review/homework.md","filePath":"weeks/14-security-and-review/homework.md"}'),n={name:"weeks/14-security-and-review/homework.md"};function s(i,e,h,d,c,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="week-14-homework--milestone-2-secure-it-review-it-hand-it-off" tabindex="-1">Week 14 homework — Milestone 2: secure it, review it, hand it off <a class="header-anchor" href="#week-14-homework--milestone-2-secure-it-review-it-hand-it-off" aria-label="Permalink to &quot;Week 14 homework — Milestone 2: secure it, review it, hand it off&quot;">​</a></h1><blockquote><p><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before). About <strong>5.5 hours</strong>, all on your <strong>capstone</strong>, plus a 15-minute walkthrough slot if yours is by appointment. This week completes <strong>Milestone 2</strong>. Work in the <a href="./../../resources/safe-loop.html">Safe Loop</a>: check first, one small step, test, read the diff, teach back, commit.</p></blockquote><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><ul><li>☐ <code>SECURITY_CHECKLIST.md</code> with evidence for every ticked item, dated this week, ending with your <strong>threat model</strong> (<a href="#1-security-checklist-and-threat-model-about-45-min">Part 1</a>)</li><li>☐ <strong>Peer review given:</strong> your written review on Canvas (the course&#39;s learning management system), shared with the author privately (🔴 AI off) (<a href="#2-finish-your-written-review-about-45-min">Part 2</a>)</li><li>☐ <strong>Response to the review you received</strong>, on Canvas, with links (<a href="#3-act-on-the-review-you-received-about-45-min">Part 3</a>)</li><li>☐ <strong>Handoff test</strong> done in both directions, gaps fixed, noted in <code>PROMPTS.md</code> (<a href="#4-the-handoff-test-about-1-h">Part 4</a>)</li><li>☐ <strong>Oral walkthrough 3</strong> done this week (🔴 AI off) (<a href="#5-prepare-for-walkthrough-3-about-30-min">Part 5</a>)</li><li>☐ Every chosen feature type works at least roughly on the production URL, and <code>npm test</code> passes (<a href="#6-project-build-time-about-125-h">Part 6</a>)</li><li>☐ <code>PROMPTS.md</code>: teach-backs, <code>Assisted-by:</code> lines, and your maintenance-task entry; reflection on Canvas (🔴 AI off) (<a href="#7-promptsmd-and-reflection-about-30-min">Part 7</a>)</li><li>☐ On Canvas: your repo link, and your <strong>production URL plus a screenshot</strong> of it working</li></ul><table tabindex="0"><thead><tr><th>Part</th><th>Time</th></tr></thead><tbody><tr><td>1. Security checklist and threat model</td><td>about 45 min</td></tr><tr><td>2. Finish your written review</td><td>about 45 min</td></tr><tr><td>3. Act on the review you received</td><td>about 45 min</td></tr><tr><td>4. The handoff test</td><td>about 1 h</td></tr><tr><td>5. Prepare for walkthrough 3</td><td>about 30 min</td></tr><tr><td>6. Project build time</td><td>about 1.25 h</td></tr><tr><td>7. <code>PROMPTS.md</code> and reflection</td><td>about 30 min</td></tr><tr><td><strong>Total</strong></td><td><strong>about 5.5 h</strong></td></tr></tbody></table><h2 id="milestone-2" tabindex="-1">Milestone 2 <a class="header-anchor" href="#milestone-2" aria-label="Permalink to &quot;Milestone 2&quot;">​</a></h2><p>The row below matches the <a href="./../../projects/capstone.html#milestones">capstone milestones</a>. Everything marked &quot;on Canvas&quot; goes there, never in a repo.</p><table tabindex="0"><thead><tr><th>Milestone</th><th>Due</th><th>Deliverables</th><th>Graded as</th></tr></thead><tbody><tr><td><strong>Milestone 2: feature complete</strong> (end of week 14)</td><td>Before week 15 Studio A</td><td>• Your <strong>second feature type</strong> working, for example Supabase with row-level security, its grants and policies saved in <code>supabase/policies.sql</code><br>• <code>SECURITY_CHECKLIST.md</code> with evidence for every ticked item, and a one-paragraph <strong>threat model</strong> of one feature<br>• <strong>Peer review given:</strong> your written review of a classmate&#39;s capstone, on Canvas<br>• <strong>Response to the review you received:</strong> what you changed (link the commits or pull request) and what you decided not to change, and why, on Canvas<br>• <strong>Handoff test:</strong> a classmate tried one small change using only your README and <code>AGENTS.md</code>; you fixed what confused them and noted it in <code>PROMPTS.md</code></td><td>Weeks 13 and 14 homework (<a href="./../../assessment/rubrics.html#weekly-labs-and-homework">weekly rubric</a>); the peer review in <a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">Reflections and peer reviews</a></td></tr></tbody></table><h2 id="core-required" tabindex="-1">Core (required) <a class="header-anchor" href="#core-required" aria-label="Permalink to &quot;Core (required)&quot;">​</a></h2><h3 id="1-security-checklist-and-threat-model-about-45-min" tabindex="-1">1. Security checklist and threat model (about 45 min) <a class="header-anchor" href="#1-security-checklist-and-threat-model-about-45-min" aria-label="Permalink to &quot;1. Security checklist and threat model (about 45 min)&quot;">​</a></h3><p>Finish your capstone&#39;s <code>SECURITY_CHECKLIST.md</code> (from the <a href="./../../templates/SECURITY_CHECKLIST.html">template</a>), carrying on from Studio A&#39;s sweep. Tick each item <strong>and</strong> paste one line of evidence: a command&#39;s output, a file name, a screenshot link (check first that it shows no keys). In particular:</p><ul><li><strong>Section 1 (secrets):</strong> run <code>npm run check:secrets</code> again after your last commit; a clean result covers old commits too.</li><li><strong>Section 3 (database):</strong> still true after this week&#39;s changes, including the sentence saying <strong>where authorization is enforced</strong>.</li><li><strong>Section 4 (XSS):</strong> the <code>&lt;img src=x onerror=alert(1)&gt;</code> test showed no alert, before and after a reload.</li><li><strong>Section 6 (agents):</strong> which parts of the lethal trifecta your setup has, and what keeps it from having all three.</li><li><strong>Threat model:</strong> finish the paragraph from Part A2. Everything that &quot;doesn&#39;t stop them yet&quot; is either fixed (listed in &quot;What I found and fixed&quot;) or in your README&#39;s Known issues.</li></ul><p>✅ <strong>Done when:</strong> every applicable box is ticked with evidence, and the threat model names who, how and what stops them.</p><h3 id="2-finish-your-written-review-about-45-min" tabindex="-1">2. Finish your written review (about 45 min) <a class="header-anchor" href="#2-finish-your-written-review-about-45-min" aria-label="Permalink to &quot;2. Finish your written review (about 45 min)&quot;">​</a></h3><p>🔴 AI off. Complete the review you started in Studio B, using the headings of <a href="./../../templates/CODE_REVIEW.html">CODE_REVIEW.md template</a>, including the compare table from your AI review. Submit it on Canvas and share it with the author privately (a Canvas comment or email), never as a file or issue in their repo. Refer to people by GitHub username. It&#39;s graded with the <a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">peer review rubric</a>.</p><p>✅ <strong>Done when:</strong> your review is on Canvas and shared with its author.</p><h3 id="3-act-on-the-review-you-received-about-45-min" tabindex="-1">3. Act on the review you received (about 45 min) <a class="header-anchor" href="#3-act-on-the-review-you-received-about-45-min" aria-label="Permalink to &quot;3. Act on the review you received (about 45 min)&quot;">​</a></h3><p>Fix the <strong>single most important issue</strong> your reviewer raised, in the Safe Loop, through a pull request. Name the issue in the commit message, for example <code>Fix XSS in list rendering raised in PR review</code>. Then write your <strong>response to the review</strong> on Canvas: what you changed (link the commits or pull request) and what you decided not to change, and why. Disagreeing with a point, with your reasoning, counts. Replying on the pull request too is ordinary code review.</p><p>✅ <strong>Done when:</strong> the fix is merged, and your response is on Canvas with links.</p><h3 id="4-the-handoff-test-about-1-h" tabindex="-1">4. The handoff test (about 1 h) <a class="header-anchor" href="#4-the-handoff-test-about-1-h" aria-label="Permalink to &quot;4. The handoff test (about 1 h)&quot;">​</a></h3><p>Can someone else change your app from your docs alone? Your partner tries <strong>one tiny change</strong> using only your <code>README.md</code> and <code>AGENTS.md</code>, with an agent and approvals on, <strong>without asking you anything</strong>. You do the same for them, about 30 minutes each way.</p><p><strong>Access, with no keys shared:</strong></p><ol><li>Your repo is public, so your partner opens it in <strong>their own</strong> Codespace (<strong>Code → Codespaces → Create codespace on main</strong>), on their account and their hours. They can&#39;t push to your repo, and don&#39;t need to.</li><li><strong>Keys stay with their owners.</strong> Nobody gets your <code>.env</code>. If the change needs the AI feature, they use their own free key in their own Codespace, or pick a change that needs none. Your <code>public/config.js</code> points their copy at your Supabase project, which is fine: the publishable key is public anyway, and RLS decides what it can do. That&#39;s part of the test.</li><li><strong>Private repo?</strong> Add your partner under <strong>Settings → Collaborators</strong> for the week, and remove them afterwards.</li></ol><p><strong>The tester</strong> picks a small change (a Studio B change-request card they didn&#39;t get, or &quot;add a footer with the app&#39;s name&quot;), tries it in 30 minutes at most using only the README and <code>AGENTS.md</code>, and writes down every place they got stuck or had to guess. They send the notes to the author in person, by chat or by email (not as an issue in the repo), then delete the Codespace (<a href="./../../setup/codespaces.html#stop-and-delete-codespaces">how</a>).</p><p><strong>The author</strong> fixes every gap in <code>README.md</code> and <code>AGENTS.md</code> in one commit (for example <code>docs: fill gaps found in handoff test</code>) and adds a short &quot;Handoff test&quot; entry to <code>PROMPTS.md</code>: what confused the tester and what changed. Don&#39;t name your partner in the commit, the docs or <code>PROMPTS.md</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Working alone?</strong> Your instructor, or a volunteer with a fresh GitHub account, does the tester&#39;s job. See the <a href="./../../resources/self-paced.html">Self-paced path</a>.</p></div><p>✅ <strong>Done when:</strong> both tests are done, your docs commit is pushed, and the <code>PROMPTS.md</code> entry is there.</p><h3 id="5-prepare-for-walkthrough-3-about-30-min" tabindex="-1">5. Prepare for walkthrough 3 (about 30 min) <a class="header-anchor" href="#5-prepare-for-walkthrough-3-about-30-min" aria-label="Permalink to &quot;5. Prepare for walkthrough 3 (about 30 min)&quot;">​</a></h3><p>Read <a href="./../../assessment/oral-walkthroughs.html#what-to-expect">What to expect</a> and the walkthrough 3 questions on the same page, then practice with a classmate, taking turns as examiner, AI off. Be ready to say, without notes, <strong>where authorization is enforced</strong>, walk through one request from the click to the database or server and back, and explain one of your tests. Before your slot: start your app, open your live URL (restore Supabase if it&#39;s paused), commit everything and close AI chat panels. The slot must be this week: week 15 has none.</p><p>✅ <strong>Done when:</strong> walkthrough 3 is done.</p><h3 id="6-project-build-time-about-125-h" tabindex="-1">6. Project build time (about 1.25 h) <a class="header-anchor" href="#6-project-build-time-about-125-h" aria-label="Permalink to &quot;6. Project build time (about 1.25 h)&quot;">​</a></h3><p>Make sure <strong>every chosen feature type works, at least roughly</strong>, at the production URL: week 15 is for polish and the demo video, not for building. Write each new test before the code it checks, merge through reviewed pull requests, and take the production-URL screenshot for Canvas (Vercel deletes old preview deployments).</p><p>✅ <strong>Done when:</strong> each chosen feature type works on the production URL, and <code>npm test</code> passes.</p><h3 id="7-promptsmd-and-reflection-about-30-min" tabindex="-1">7. <code>PROMPTS.md</code> and reflection (about 30 min) <a class="header-anchor" href="#7-promptsmd-and-reflection-about-30-min" aria-label="Permalink to &quot;7. `PROMPTS.md` and reflection (about 30 min)&quot;">​</a></h3><ul><li><strong><code>PROMPTS.md</code> (10 min):</strong> a 2–3 sentence teach-back before every agent commit this week, an <code>Assisted-by: [tool]</code> line on every AI-assisted commit, and your AI-off maintenance-task entry.</li><li><strong>Reflection (20 min), 🔴 AI off:</strong> write it yourself and submit it on Canvas, never in your repo (<a href="./../../templates/REFLECTION.html">REFLECTION.md template</a> is a starting shape). Anchor it in one concrete moment: when you got stuck (or didn&#39;t) in the maintenance task, a review comment that changed your mind, or where your handoff tester got lost. How much did you <em>feel</em> you understood your app, compared with what you could do with the AI off?</li></ul><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><ul><li><strong>Protect <code>main</code>.</strong> The starter already runs <code>npm test</code> on every push (your repo&#39;s <strong>Actions</strong> tab). Turn on <a href="./../../resources/glossary.html#branch-protection">branch protection</a> so <code>main</code> only accepts pull requests with a green test run.</li><li><strong>Fix a second review issue</strong>, or another &quot;doesn&#39;t stop them yet&quot; from your threat model.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Supabase free projects <strong>pause after about a week without activity</strong>. Open yours before each studio, your walkthrough and the Project Fair, and restore it if needed (<a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>).</p></div><h2 id="looking-ahead" tabindex="-1">Looking ahead <a class="header-anchor" href="#looking-ahead" aria-label="Permalink to &quot;Looking ahead&quot;">​</a></h2><p>Week 15 is <strong>Ship It</strong>: polish, accessibility, known issues, a final security pass and your demo video, with no exit ticket and no walkthrough. The <strong>Project Fair</strong> is in finals week (week 16), in the course&#39;s final exam slot.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up:</strong> Milestone 2 in place: every chosen feature type at least roughly working at the production URL, <code>SECURITY_CHECKLIST.md</code> with evidence, and walkthrough 3 done. Week 15 polishes and ships what you have; it leaves no time to build a missing feature. Behind? Tell your instructor before Studio A, and come to office hours.</p></div>',41)])])}const p=t(n,[["render",s]]);export{m as __pageData,p as default};
